From a8cabc612b16834260831a8163ae4b479b5c33a5 Mon Sep 17 00:00:00 2001
From: Yu Watanabe <watanabe.yu+github@gmail.com>
Date: Wed, 11 Oct 2017 12:27:13 +0900
Subject: [PATCH] core: fix segfault in compile_bind_mounts() when BindPaths=
 or BindReadOnlyPaths= is set

This fixes a bug introduced by 6c47cd7d3bf35c8158a0737f34fe2c5dc95e72d6.

Fixes #7055.

diff --git a/src/core/execute.c b/src/core/execute.c
index d7d2ce4947..e64afe8e9c 100644
--- a/src/core/execute.c
+++ b/src/core/execute.c
@@ -2161,7 +2161,7 @@ static int compile_bind_mounts(
         if (!bind_mounts)
                 return -ENOMEM;

-        for (i = 0; context->n_bind_mounts; i++) {
+        for (i = 0; i < context->n_bind_mounts; i++) {
                 BindMount *item = context->bind_mounts + i;
                 char *s, *d;

-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by an incorrect loop condition in the `compile_bind_mounts` function, which used `context->n_bind_mounts` as the loop condition instead of comparing the loop index `i` to `context->n_bind_mounts`. This led to potential out-of-bounds access and a segmentation fault when the number of bind mounts was set, as the loop could continue indefinitely or not execute properly, depending on the value of `context->n_bind_mounts`.

        Commit message:
        core: fix segfault in compile_bind_mounts() when BindPaths=
 or BindReadOnlyPaths= is set

This fixes a bug introduced by 6c47cd7d3bf35c8158a0737f34fe2c5dc95e72d6.

Fixes #7055.  

        Patch:

 static int compile_bind_mounts(
                 const ExecContext *context,
                 const ExecParameters *params,
                 BindMount **ret_bind_mounts,
                 unsigned *ret_n_bind_mounts,
                 char ***ret_empty_directories) {

         _cleanup_strv_free_ char **empty_directories = NULL;
         BindMount *bind_mounts;
         unsigned n, h = 0, i;
         ExecDirectoryType t;
         int r;

         assert(context);
         assert(params);
         assert(ret_bind_mounts);
         assert(ret_n_bind_mounts);
         assert(ret_empty_directories);

         n = context->n_bind_mounts;
         for (t = 0; t < _EXEC_DIRECTORY_TYPE_MAX; t++) {
                 if (!params->prefix[t])
                         continue;

                 n += strv_length(context->directories[t].paths);
         }

         if (n <= 0) {
                 *ret_bind_mounts = NULL;
                 *ret_n_bind_mounts = 0;
                 *ret_empty_directories = NULL;
                 return 0;
         }

         bind_mounts = new(BindMount, n);
         if (!bind_mounts)
                 return -ENOMEM;

-        for (i = 0; context->n_bind_mounts; i++) {
+        for (i = 0; i < context->n_bind_mounts; i++) {
                 BindMount *item = context->bind_mounts + i;
                 char *s, *d;

                 s = strdup(item->source);
                 if (!s) {
                         r = -ENOMEM;
                         goto finish;
                 }

                 d = strdup(item->destination);
                 if (!d) {
                         free(s);
                         r = -ENOMEM;
                         goto finish;
                 }

                 bind_mounts[h++] = (BindMount) {
                         .source = s,
                         .destination = d,
                         .read_only = item->read_only,
                         .recursive = item->recursive,
                         .ignore_enoent = item->ignore_enoent,
                 };
         }

         for (t = 0; t < _EXEC_DIRECTORY_TYPE_MAX; t++) {
                 char **suffix;

                 if (!params->prefix[t])
                         continue;

                 if (strv_isempty(context->directories[t].paths))
                         continue;

                 if (context->dynamic_user && t != EXEC_DIRECTORY_CONFIGURATION) {
                         char *private_root;

                         /* So this is for a dynamic user, and we need to make sure the process can access its own
                          * directory. For that we overmount the usually inaccessible "private" subdirectory with a
                          * tmpfs that makes it accessible and is empty except for the submounts we do this for. */

                         private_root = strjoin(params->prefix[t], "/private");
                         if (!private_root) {
                                 r = -ENOMEM;
                                 goto finish;
                         }

                         r = strv_consume(&empty_directories, private_root);
                         if (r < 0) {
                                 r = -ENOMEM;
                                 goto finish;
                         }
                 }

                 STRV_FOREACH(suffix, context->directories[t].paths) {
                         char *s, *d;

                         if (context->dynamic_user && t != EXEC_DIRECTORY_CONFIGURATION)
                                 s = strjoin(params->prefix[t], "/private/", *suffix);
                         else
                                 s = strjoin(params->prefix[t], "/", *suffix);
                         if (!s) {
                                 r = -ENOMEM;
                                 goto finish;
                         }

                         d = strdup(s);
                         if (!d) {
                                 free(s);
                                 r = -ENOMEM;
                                 goto finish;
                         }

                         bind_mounts[h++] = (BindMount) {
                                 .source = s,
                                 .destination = d,
                                 .read_only = false,
                                 .recursive = true,
                                 .ignore_enoent = false,
                         };
                 }
         }

         assert(h == n);

         *ret_bind_mounts = bind_mounts;
         *ret_n_bind_mounts = n;
         *ret_empty_directories = empty_directories;

         empty_directories = NULL;

         return (int) n;

 finish:
         bind_mount_free_many(bind_mounts, h);
         return r;
 }



